namespace Invoicing;

/// <summary>Resolves the VAT due for a net amount given account and jurisdiction.</summary>
public sealed class VatResolver
{
    public decimal Resolve(Account account, decimal net, string countryCode)
    {
        if (net <= 0m)
            return 0m;

        var jurisdictionRate = GetJurisdictionRate(countryCode);
        var accountRate = ApplyAccountRules(jurisdictionRate, account.Kind, net);
        var finalRate = ApplyHighValueCap(accountRate, net);

        return net * finalRate;
    }

    private static decimal GetJurisdictionRate(string countryCode) =>
        countryCode switch
        {
            "GB" => 0.20m,
            "DE" => 0.19m,
            "FR" => 0.20m,
            "IE" => 0.23m,
            _ => 0m
        };

    private static decimal ApplyAccountRules(decimal rate, AccountKind accountKind, decimal net)
    {
        if (accountKind == AccountKind.Government)
            return 0m;

        return accountKind == AccountKind.Business && net > 10000m
            ? rate * 0.5m
            : rate;
    }

    private static decimal ApplyHighValueCap(decimal rate, decimal net) =>
        rate > 0m && net > 100000m
            ? Math.Min(rate, 0.15m)
            : rate;
}
